import type { APIRequestContext } from '@playwright/test';
import { ResourceApi, ok, type Entity } from './base';

export interface JournalLine {
  account: string;
  debit: number;
  credit: number;
}
export interface JournalEntry extends Entity {
  lines: JournalLine[];
}

class Postable extends ResourceApi {
  post(id: string): Promise<Entity> {
    return this.action(id, 'post');
  }
}

class JournalEntries extends Postable {
  /** The entry generated by a source document, e.g. a vendor bill. */
  async forSource(sourceType: string, sourceId: string): Promise<JournalEntry> {
    const [entry] = await this.http
      .get(this.resource, { params: { sourceType, sourceId } })
      .then((r) => ok<JournalEntry[]>(r));
    if (!entry) throw new Error(`No journal entry for ${sourceType} ${sourceId}`);
    return entry;
  }
}

class FiscalPeriods extends ResourceApi {
  close(id: string): Promise<Entity> {
    return this.action(id, 'close');
  }
}

/** Accounting app: bills, invoices, payments, journals, periods. */
export class AccountingApi {
  readonly vendorBills: Postable;
  readonly customerInvoices: Postable;
  readonly payments: Postable;
  readonly journalEntries: JournalEntries;
  readonly periods: FiscalPeriods;

  constructor(private readonly http: APIRequestContext) {
    this.vendorBills = new Postable(http, 'vendor-bills');
    this.customerInvoices = new Postable(http, 'customer-invoices');
    this.payments = new Postable(http, 'payments');
    this.journalEntries = new JournalEntries(http, 'journal-entries');
    this.periods = new FiscalPeriods(http, 'fiscal-periods');
  }

  async trialBalance(): Promise<{ totalDebit: number; totalCredit: number }> {
    return this.http.get('reports/trial-balance').then((r) => ok(r));
  }
}
